  "inlineSchema": "// This is your Prisma schema file for Project Rina.\n// Learn more: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Users ───────────────────────────────────────────────────────\n// Hardcoded auth (maroon / rina) — DB stores profiles & settings.\nmodel User {\n  id          String   @id @default(cuid())\n  username    String   @unique @db.VarChar(50) // 'maroon' or 'rina'\n  displayName String   @db.VarChar(100)\n  avatarUrl   String?\n  timezone    String   @default(\"UTC\") // Africa/Casablanca or Europe/Moscow\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  messages           Message[]\n  cycleEntries       CycleEntry[]\n  moviesAdded        Movie[]\n  timeCapsules       TimeCapsule[]\n  scrapbookPhotos    ScrapbookPhoto[]\n  goals              Goal[]\n  pushSubs           PushSubscription[]\n  calendarEvents     CalendarEvent[]\n  countdowns         Countdown[]\n  whiteboardSessions WhiteboardSession[]\n}\n\n// ─── Calendar Events ─────────────────────────────────────────────\nmodel CalendarEvent {\n  id          String    @id @default(cuid())\n  title       String    @db.VarChar(200)\n  description String?   @db.VarChar(2000)\n  startTime   DateTime\n  endTime     DateTime?\n  type        EventType @default(SHARED)\n  creatorId   String\n  allDay      Boolean   @default(false)\n  color       String?   @db.VarChar(7) // hex override\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  creator User @relation(fields: [creatorId], references: [id], onDelete: Cascade)\n\n  @@index([startTime])\n  @@index([type])\n  @@index([creatorId])\n}\n\nenum EventType {\n  WORK\n  SHARED\n}\n\n// ─── Period Tracker ──────────────────────────────────────────────\nmodel CycleEntry {\n  id            String   @id @default(cuid())\n  userId        String\n  date          DateTime @db.Date\n  flowIntensity Int?     @db.SmallInt // 0-4 scale\n  symptoms      String[] // e.g. [\"cramps\", \"bloating\"]\n  temperature   Float? // basal body temp\n  notes         String?\n  createdAt     DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, date])\n  @@index([date])\n}\n\n// ─── Movie Watchlist ─────────────────────────────────────────────\nmodel Movie {\n  id           String    @id @default(cuid())\n  tmdbId       Int       @unique\n  title        String    @db.VarChar(300)\n  overview     String?\n  posterPath   String?\n  backdropPath String?\n  releaseDate  DateTime?\n  watched      Boolean   @default(false)\n  watchedAt    DateTime?\n  rating       Int?      @db.SmallInt // 1-10\n  addedBy      String\n  createdAt    DateTime  @default(now())\n\n  user User @relation(fields: [addedBy], references: [id], onDelete: Cascade)\n\n  @@index([watched])\n  @@index([addedBy])\n}\n\n// ─── Chat Messages ───────────────────────────────────────────────\nmodel Message {\n  id        String      @id @default(cuid())\n  senderId  String\n  content   String      @db.VarChar(4000)\n  type      MessageType @default(TEXT)\n  mediaUrl  String?\n  replyToId String?\n  editedAt  DateTime?\n  createdAt DateTime    @default(now())\n\n  sender  User      @relation(fields: [senderId], references: [id], onDelete: Cascade)\n  replyTo Message?  @relation(\"MessageReplies\", fields: [replyToId], references: [id], onDelete: SetNull)\n  replies Message[] @relation(\"MessageReplies\")\n\n  @@index([createdAt])\n  @@index([senderId])\n}\n\nenum MessageType {\n  TEXT\n  IMAGE\n  AUDIO\n  VIDEO\n}\n\n// ─── Time Capsule ────────────────────────────────────────────────\nmodel TimeCapsule {\n  id            String    @id @default(cuid())\n  title         String    @db.VarChar(200)\n  description   String?   @db.VarChar(2000)\n  encryptedData String // AES-256 encrypted blob (base64)\n  mediaType     String    @db.VarChar(20) // 'audio' | 'video' | 'text'\n  unlockAt      DateTime\n  creatorId     String\n  openedAt      DateTime?\n  createdAt     DateTime  @default(now())\n\n  creator User @relation(fields: [creatorId], references: [id], onDelete: Cascade)\n\n  @@index([unlockAt])\n  @@index([creatorId])\n}\n\n// ─── Visit Countdowns ────────────────────────────────────────────\nmodel Countdown {\n  id         String   @id @default(cuid())\n  title      String   @db.VarChar(200)\n  targetDate DateTime\n  location   String?  @db.VarChar(200)\n  imageUrl   String?\n  createdBy  String\n  createdAt  DateTime @default(now())\n\n  creator User @relation(fields: [createdBy], references: [id], onDelete: Cascade)\n\n  @@index([targetDate])\n  @@index([createdBy])\n}\n\n// ─── Scrapbook Photos (3D Map) ───────────────────────────────────\nmodel ScrapbookPhoto {\n  id           String    @id @default(cuid())\n  s3Key        String    @db.VarChar(500) // S3/MinIO object key\n  thumbnailUrl String?\n  lat          Float?\n  lng          Float?\n  caption      String?   @db.VarChar(500)\n  takenAt      DateTime?\n  exifData     Json? // stored as JSONB\n  uploadedBy   String\n  createdAt    DateTime  @default(now())\n\n  uploader User @relation(fields: [uploadedBy], references: [id], onDelete: Cascade)\n\n  @@index([lat, lng])\n  @@index([uploadedBy])\n}\n\n// ─── Financial Goals ─────────────────────────────────────────────\nmodel Goal {\n  id            String    @id @default(cuid())\n  title         String    @db.VarChar(200)\n  targetAmount  Int // stored in smallest currency unit (cents)\n  currentAmount Int       @default(0)\n  currency      String    @default(\"EUR\") @db.VarChar(3)\n  deadline      DateTime?\n  icon          String?   @db.VarChar(50) // emoji or lucide icon name\n  createdBy     String\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  creator User @relation(fields: [createdBy], references: [id], onDelete: Cascade)\n\n  @@index([createdBy])\n}\n\n// ─── Whiteboard Session Metadata ─────────────────────────────────\n// Actual stroke data lives in Yjs; this stores session metadata.\nmodel WhiteboardSession {\n  id        String   @id @default(cuid())\n  name      String   @db.VarChar(200)\n  createdBy String\n  ydocState Bytes? // optional snapshot backup\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  creator User @relation(fields: [createdBy], references: [id], onDelete: Cascade)\n\n  @@index([createdBy])\n}\n\n// ─── Web Push Subscriptions ──────────────────────────────────────\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n",
